(()=>{const root=document.documentElement,body=document.body,header=document.querySelector('.site-header');const setLang=lang=>{lang=lang==='en'?'en':'ko';root.lang=lang;try{localStorage.setItem('rebornsoft_lang',lang)}catch{}document.querySelectorAll('[data-ko][data-en]').forEach(el=>{el.textContent=el.dataset[lang]});document.querySelectorAll('[data-alt-ko]').forEach(el=>{el.alt=el.dataset[lang==='ko'?'altKo':'altEn']});document.querySelectorAll('[data-lang]').forEach(btn=>{const on=btn.dataset.lang===lang;btn.classList.toggle('active',on);btn.setAttribute('aria-pressed',String(on))});};let saved='ko';try{saved=localStorage.getItem('rebornsoft_lang')||'ko'}catch{}setLang(saved);document.querySelectorAll('[data-lang]').forEach(btn=>btn.addEventListener('click',()=>setLang(btn.dataset.lang)));requestAnimationFrame(()=>body.classList.add('loaded'));const scrollHeader=()=>{header?.classList.toggle('scrolled',scrollY>48);body.classList.toggle('is-scrolled',scrollY>120)};addEventListener('scroll',scrollHeader,{passive:true});scrollHeader();const trigger=document.querySelector('.menu-trigger'),panel=document.querySelector('.mobile-panel');const closeMenu=()=>{if(!trigger||!panel)return;trigger.setAttribute('aria-expanded','false');panel.classList.remove('open');panel.setAttribute('aria-hidden','true');body.classList.remove('menu-open')};trigger?.addEventListener('click',()=>{const open=trigger.getAttribute('aria-expanded')!=='true';trigger.setAttribute('aria-expanded',String(open));panel.classList.toggle('open',open);panel.setAttribute('aria-hidden',String(!open));body.classList.toggle('menu-open',open)});panel?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});const AUTO_REVEAL='h1,h2,h3,p,.link,.status,.tag,.card-eyebrow,li,.engagement,.proof-row,.timeline-row,.phase,.contact-row,.fact,.evo-label,.dna,.section-head';document.querySelectorAll('main').forEach(m=>{m.querySelectorAll(AUTO_REVEAL).forEach(el=>{if(el.closest('.hero-copy,.cap-flow-step,.cap-flow-accordion-item'))return;const owner=el.closest('.reveal');if(owner&&owner!==el)return;el.classList.add('reveal')})});const revealGroups=new Map();document.querySelectorAll('.reveal').forEach(el=>{const p=el.parentElement,i=revealGroups.get(p)||0;el.style.setProperty('--reveal-i',String(Math.min(i,8)));revealGroups.set(p,i+1)});const obs=new IntersectionObserver(es=>es.forEach(e=>{e.target.classList.toggle('visible',e.isIntersecting)}),{threshold:.15,rootMargin:'0px 0px -8%'});document.querySelectorAll('.reveal').forEach(el=>obs.observe(el));const flow=document.querySelector('.cap-flow');if(flow){const flowSteps=[...flow.querySelectorAll('.cap-flow-step')],flowVisuals=[...flow.querySelectorAll('.cap-flow-visual')];const setActive=key=>{flowSteps.forEach(s=>{const on=s.dataset.step===key;s.classList.toggle('active',on);s.setAttribute('aria-selected',String(on))});flowVisuals.forEach(v=>v.classList.toggle('active',v.dataset.step===key))};const hoverCapable=matchMedia('(hover:hover)').matches;flowSteps.forEach(s=>{s.addEventListener('click',()=>setActive(s.dataset.step));if(hoverCapable)s.addEventListener('mouseenter',()=>setActive(s.dataset.step))});const mobileSteps=[...document.querySelectorAll('.cap-flow-accordion-item')];mobileSteps.forEach(item=>{const trigger=item.querySelector('.cap-flow-accordion-trigger');trigger?.addEventListener('click',()=>{const open=!item.classList.contains('open');mobileSteps.forEach(x=>{x.classList.remove('open');x.querySelector('.cap-flow-accordion-trigger')?.setAttribute('aria-expanded','false')});if(open){item.classList.add('open');trigger.setAttribute('aria-expanded','true')}})})}})();
(()=>{document.querySelectorAll('.progressive-image__full').forEach(img=>{const box=img.closest('[data-progressive]');const reveal=()=>box?.classList.add('is-ready');if(img.complete&&img.naturalWidth>0)reveal();else img.addEventListener('load',reveal,{once:true})})})();
(()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const layers=[...document.querySelectorAll('[data-parallax]')],bgLayers=[...document.querySelectorAll('[data-parallax-bg]')];if(!layers.length&&!bgLayers.length)return;const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));let ticking=false;const update=()=>{const vh=innerHeight;layers.forEach(el=>{const speed=parseFloat(el.dataset.parallax)||.2,max=parseFloat(el.dataset.parallaxMax)||40,host=el.parentElement,r=host.getBoundingClientRect();if(r.bottom<0||r.top>vh){return}const center=r.top+r.height/2,delta=clamp((center-vh/2)*speed,-max,max);el.style.transform=`translate3d(0, ${delta.toFixed(1)}px, 0)`});bgLayers.forEach(el=>{const speed=parseFloat(el.dataset.parallaxBg)||.15,max=parseFloat(el.dataset.parallaxMax)||30,r=el.getBoundingClientRect();if(r.bottom<0||r.top>vh){return}const center=r.top+r.height/2,delta=clamp((center-vh/2)*speed,-max,max);el.style.backgroundPosition=`center calc(50% + ${delta.toFixed(1)}px)`});ticking=false};const onScroll=()=>{if(!ticking){requestAnimationFrame(update);ticking=true}};addEventListener('scroll',onScroll,{passive:true});addEventListener('resize',onScroll);update()})();
